[CmdletBinding()]
param([Parameter(Mandatory=$true)][string]$ManifestPath,[Parameter(Mandatory=$true)][string]$OfflinePackageDirectory)
$ErrorActionPreference='Stop';$OutputEncoding=[Console]::OutputEncoding=[Text.UTF8Encoding]::new($false);$root=[IO.Path]::GetFullPath((Get-Location).Path).TrimEnd('\')+'\';$manifestFull=(Resolve-Path -LiteralPath $ManifestPath -ErrorAction Stop).Path;$offlineFull=if([IO.Path]::IsPathRooted($OfflinePackageDirectory)){[IO.Path]::GetFullPath($OfflinePackageDirectory)}else{[IO.Path]::GetFullPath((Join-Path $root $OfflinePackageDirectory))};if(-not $manifestFull.StartsWith($root,[StringComparison]::OrdinalIgnoreCase)-or -not $offlineFull.StartsWith($root,[StringComparison]::OrdinalIgnoreCase)){throw 'Paths must remain under project root.'}
$validator=Join-Path $root 'ES/Automation/WebPageStudio/Test-ESWebPageStudioLocaleBundleFreshness.ps1';$result=& $validator -ManifestPath $manifestFull -OfflinePackageDirectory $offlineFull|ConvertFrom-Json;$manifest=Get-Content -Raw -Encoding UTF8 $manifestFull|ConvertFrom-Json;$offlineEvidence=[ordered]@{directory=$offlineFull.Replace($root,'').Replace('\','/');status=($result.targets|? target -eq 'offline-package').status;passedCount=($result.targets|? target -eq 'offline-package').passedCount;failedCount=($result.targets|? target -eq 'offline-package').failedCount;validatedUtc=[DateTime]::UtcNow.ToString('o')};if($null -eq $manifest.freshnessEvidence){$manifest|Add-Member -NotePropertyName freshnessEvidence -NotePropertyValue ([pscustomobject]@{})};$manifest.freshnessEvidence|Add-Member -NotePropertyName offlinePackage -NotePropertyValue $offlineEvidence -Force;[IO.File]::WriteAllText($manifestFull,($manifest|ConvertTo-Json -Depth 15),[Text.UTF8Encoding]::new($false));[pscustomobject]@{status=$offlineEvidence.status;manifestPath=$manifestFull;offlinePackage=$offlineEvidence.directory}|ConvertTo-Json -Depth 8
